            "schema": {
              "type": "string",
              "enum": [
                "createdDate",
                "orderId"
              ]
            }
          },
          {
            "name": "sortOrders",
            "in": "query",
            "description": "A list of orders to apply to the respective sortFields. The only accepted sortOrders will be ASC and DESC (case insensitive)",
