              "DECLINED",
              "APPROVED",
              "SETTLED",
              "EXPIRED"
            ]
          },
          "reason": {
            "type": "string",
            "description": "The reason why this activity was declined. Only applies to activities with status DECLINED",
            "example": "Account has insufficient funds"
          },
