          "billingAmount",
          "billingCurrency",
          "cardId",
          "createdDate",
          "fxRate",
          "id",
          "mcc",
          "orderId",
          "transactionAmount",
          "transactionCurrency",
          "type"
        ]
      },
      "channelmanager.MessageResponse": {
        "type": "object",
        "properties": {
          "field": {
            "type": "string"
